CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS visitors(id uuid PRIMARY KEY, privacy_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS consent_records(id uuid PRIMARY KEY,visitor_id uuid NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,version text NOT NULL,upload_hash text NOT NULL UNIQUE,granted_at timestamptz NOT NULL DEFAULT now(),revoked_at timestamptz);
CREATE INDEX IF NOT EXISTS consent_visitor ON consent_records(visitor_id);
CREATE TABLE IF NOT EXISTS sessions(id uuid PRIMARY KEY,visitor_id uuid NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,started_at timestamptz NOT NULL,last_at timestamptz NOT NULL,build text NOT NULL,release text NOT NULL,device text NOT NULL,orientation text NOT NULL,animation text NOT NULL,diagnostic boolean NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_day ON sessions(started_at,diagnostic);
CREATE TABLE IF NOT EXISTS run_summaries(visitor_id uuid NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,run_id uuid NOT NULL,started_at timestamptz,last_at timestamptz NOT NULL,ended_at timestamptz,race text NOT NULL,difficulty text NOT NULL,build text NOT NULL,diagnostic boolean NOT NULL,seconds double precision NOT NULL DEFAULT 0,highest_stage integer NOT NULL DEFAULT 1,highest_round integer NOT NULL DEFAULT 0,player_level integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'incomplete',PRIMARY KEY(visitor_id,run_id));
CREATE INDEX IF NOT EXISTS runs_filters ON run_summaries(last_at,race,difficulty,build,diagnostic);
CREATE TABLE IF NOT EXISTS stage_summaries(visitor_id uuid NOT NULL,run_id uuid NOT NULL,mode text NOT NULL,stage integer NOT NULL,observed_at timestamptz NOT NULL,data jsonb NOT NULL,PRIMARY KEY(visitor_id,run_id,mode,stage),FOREIGN KEY(visitor_id,run_id) REFERENCES run_summaries(visitor_id,run_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS events(visitor_id uuid NOT NULL REFERENCES visitors(id) ON DELETE CASCADE,event_id text NOT NULL,consent_id uuid NOT NULL REFERENCES consent_records(id) ON DELETE CASCADE,session_id uuid NOT NULL REFERENCES sessions(id) ON DELETE CASCADE,run_id uuid,kind text NOT NULL,occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),build text NOT NULL,release text NOT NULL,diagnostic boolean NOT NULL,data jsonb NOT NULL,PRIMARY KEY(visitor_id,event_id));
CREATE INDEX IF NOT EXISTS events_day_kind ON events(occurred_at,kind,diagnostic);
CREATE TABLE IF NOT EXISTS daily_metrics(day date NOT NULL,dimensions text NOT NULL,data jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(day,dimensions));
CREATE TABLE IF NOT EXISTS feedback(id uuid PRIMARY KEY,receipt_hash text NOT NULL,category text NOT NULL,body text NOT NULL,contact text NOT NULL DEFAULT '',summary jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'new',priority integer NOT NULL DEFAULT 1,tags jsonb NOT NULL DEFAULT '[]',admin_note text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS feedback_inbox ON feedback(created_at,status,category);
CREATE TABLE IF NOT EXISTS admin_users(id uuid PRIMARY KEY,username text UNIQUE NOT NULL,password_hash text NOT NULL,can_export_contacts boolean NOT NULL DEFAULT false,disabled boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,csrf_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS admin_audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id uuid REFERENCES admin_users(id) ON DELETE SET NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_throttles(key text PRIMARY KEY,failures integer NOT NULL DEFAULT 0,window_start timestamptz NOT NULL,blocked_until timestamptz);
CREATE TABLE IF NOT EXISTS deletion_manifest(subject_hash text PRIMARY KEY,scope text NOT NULL CHECK(scope IN ('visitor','feedback')),deleted_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL);
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
ALTER TABLE feedback ADD COLUMN IF NOT EXISTS consent_version text NOT NULL DEFAULT '2026-10-06.1';
